"""Inspect RDSR source semantics and original bounded busy polling, without guest execution."""
import argparse,hashlib,json,struct
from pathlib import Path
from capstone import Cs,CS_ARCH_ARM,CS_MODE_THUMB,CS_MODE_MCLASS
from pypdf import PdfReader
from native_replay import parse_log
from pinned_main import load_pinned_main

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('simulator',type=Path);p.add_argument('output',type=Path);a=p.parse_args();s=a.simulator;o=a.output;o.mkdir(mode=0o700);checks=[];cases=[]
 def check(n,v):
  if not v:raise ValueError(n)
  checks.append(n)
 research=s/'mspi1-pio-research-01';pin=json.loads((research/'datasheet-source.json').read_text());pdf=research/'mx25u25643g-v1.1.pdf';check('manufacturer-PDF-pin',hashlib.sha256(pdf.read_bytes()).hexdigest()==pin['sha256']);r=PdfReader(pdf);texts={n:r.pages[n-1].extract_text() for n in [32,36]}
 for n,t in texts.items():(o/f'datasheet-page-{n}.txt').write_text(t)
 t=' '.join(texts[32].split());check('RDSR-instruction-and-sequence','9-8. Read Status Register (RDSR)' in t and '05h' in t and 'sending RDSR instruction code→ Status Register data out on SO.' in t);check('RDSR-available-while-busy','can be read at any time' in t and 'even in program/erase/write status register condition' in t)
 t=' '.join(texts[36].split());check('status-WIP-and-WEL-meaning','WIP bit sets to 0' in t and 'not in progress of program/erase/write status register cycle' in t and 'WEL needs to be set to “1”' in t);check('NV-config-not-reset-evidence','non-volatile bit' in t and 'Quad Enable (QE) bit is a non-volatile bit' in t)
 md=Cs(CS_ARCH_ARM,CS_MODE_THUMB|CS_MODE_MCLASS)
 for key,bundle,delta in [('stock24','stock-2.4.0.24.bin',0),('stock23','stock-2.3.0.24.bin',0x4d18),('cfw','faceclaw-38-research-only.bin',0x4d18)]:
  d=s/'mspi1-zero-main-01'/key;_,raw=load_pinned_main((s/'inputs/verified-01'/bundle).read_bytes());check(key+'-original-main',raw==(d/'main.bin').read_bytes());log=(d/'renode.log').read_text();v=parse_log(log);check(key+'-saved-report',v==json.loads((d/'report.json').read_text())['observed']);g=[x for x in v['guards'] if x['accesses']];check(key+'-RX1-request',len(g)==1 and g[0]['address']==0x40061000 and g[0]['value']==0x10441 and g[0]['operation']=='write');cfg=[json.loads(x.split(' ',1)[1])['registers'] for x in log.splitlines() if x.startswith('BLACKWALL_MSPI1_CONFIG ')];check(key+'-RDSR-configuration',len(cfg)==1 and cfg[0]['12']==5 and cfg[0]['132']==0x3010061);st=v['stack_context'];b=struct.pack('<32I',*st['words']);off=v['register_context']['r1']-st['base'];check(key+'-descriptor',off==36 and struct.unpack_from('<I',b,off)[0]==1 and b[off+6]==0 and b[off+12]==1 and struct.unpack_from('<H',b,off+14)[0]==5 and b[off+16]==1)
  entry=0x47b750-delta;end=0x47b7cc-delta;code=list(md.disasm(raw[entry-0x438000:end-0x438000],entry));m={x.address:(x.mnemonic,x.op_str) for x in code};check(key+'-status-helper-entry',m.get(entry)==('push','{r0, r1, r2, r3, r4, lr}') and code[-1].address==end-2 and code[-1].mnemonic=='pop');expected={0xc:('movs','r0, #1'),0x10:('add','r3, sp, #8'),0x12:('movs','r2, #0'),0x14:('movs','r1, #0'),0x16:('movs','r0, #5'),0x18:('bl','#'+hex(0x47b5e0-delta)),0x1c:('movs','r4, r0'),0x1e:('cmp','r4, #0'),0x20:('beq','#'+hex(entry+0x6a)),0x66:('movs','r0, r4'),0x68:('b','#'+hex(entry+0x78)),0x6a:('ldrb.w','r0, [sp, #8]'),0x6e:('lsls','r0, r0, #0x1f'),0x70:('bpl','#'+hex(entry+0x76)),0x72:('movs','r0, #1'),0x74:('b','#'+hex(entry+0x78)),0x76:('movs','r0, #0'),0x78:('add','sp, #0x10'),0x7a:('pop','{r4, pc}')};check(key+'-status-read-and-bit0-branch',all(m.get(entry+x)==pair for x,pair in expected.items()));check(key+'-actual-status-caller-frame',st['words'][21]==entry+0x1d)
  poll=0x47b7e0-delta;code2=list(md.disasm(raw[poll-0x438000:poll+0x52-0x438000],poll));m2={x.address:(x.mnemonic,x.op_str) for x in code2};check(key+'-poll-entry',m2.get(poll)==('push','{r3, r4, r5, lr}') and m2.get(poll+0x50)==('pop','{r1, r4, r5, pc}'));expected2={4:('movs','r5, #0'),8:('movs','r0, #5'),0xe:('adds','r5, r5, #1'),0x10:('cmp','r5, #0xc8'),0x12:('bhs','#'+hex(poll+0x20)),0x14:('bl','#'+hex(entry)),0x18:('cmp','r0, #0'),0x1a:('bne','#'+hex(poll+8)),0x1c:('movs','r0, #0'),0x26:('cmp','r5, r4'),0x28:('bhs','#'+hex(poll+0x4e)),0x42:('bl','#'+hex(entry)),0x46:('cmp','r0, #0'),0x48:('bne','#'+hex(poll+0x24)),0x4e:('movs','r0, #1')};check(key+'-bounded-poll-branches',all(m2.get(poll+x)==pair for x,pair in expected2.items()));check(key+'-actual-poll-caller-frame',st['words'][27]==poll+0x19)
  (o/(key+'-status-and-poll.asm')).write_text('\n'.join(hex(x.address)+' '+x.mnemonic+' '+x.op_str for x in code+code2)+'\n');cases.append(dict(case=key,status_helper=hex(entry),poll_helper=hex(poll),status_bit_inspected=0,first_loop_bound=200,RDSR_completed=False,firmware_busy_branch_executed=False))
 (o/'report.json').write_text(json.dumps(dict(passed=True,count=len(checks),checks=checks,cases=cases,scope='manufacturer status contract and static original polling branches only; no RDSR response, branch execution, physical NOR state or full boot proof'),indent=2)+'\n');print(json.dumps(dict(passed=True,count=len(checks))))
if __name__=='__main__':main()
